const setCampaignStatus = `-- name: SetCampaignStatus :one
UPDATE campaigns SET status = $1,
    scheduled_at = CASE WHEN $1::text = 'scheduled' THEN $2 ELSE scheduled_at END,
    started_at   = CASE WHEN $1::text IN ('preparing', 'running') THEN coalesce(started_at, now()) ELSE started_at END,
    finished_at  = CASE WHEN $1::text IN ('completed', 'cancelled', 'failed') THEN now() ELSE finished_at END,
    dispatch_gen = CASE WHEN $1::text = 'running' THEN dispatch_gen + 1 ELSE dispatch_gen END,
    last_error   = CASE WHEN $1::text = 'failed' THEN $3 ELSE last_error END,
    updated_at   = now()
WHERE id = $4 AND status = ANY($5::text[])
RETURNING id, name, status, phone_number_id, template_name, template_language, template_params, audience, scheduled_at, started_at, finished_at, materialize_cursor, dispatch_gen, window_size, total_recipients, last_error, created_by, created_at, updated_at, progress_published_at, progress_dirty, offer_id
`

